#!/usr/bin/env python3
"""Build the native bestiary contact-sheet / playback inspector, without remaking art."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
species=json.loads((root/'data/bestiary.json').read_text())['species']
rows=[{'id':key,'name':v['name'],'windup':v['windup'],'abilities':[x['name'] for x in v['abilities']]} for key,v in species.items()]
html='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cổ giới · Quái thú 0.45</title>
<style>*{box-sizing:border-box}body{margin:0;background:#242d27;color:#e6d9b9;font:16px/1.55 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:34px 22px}a{color:#cebe85}header{border-bottom:1px solid #69705b;padding-bottom:20px}h1{margin:6px 0;font:36px/1.2 Georgia,serif}p{color:#c2c9b4}small{letter-spacing:.18em;color:#b9a878}.tools{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0 14px}button,select{font:inherit;color:#ecdfbd;background:#364135;border:1px solid #7c8066;padding:9px 12px;border-radius:3px}button{cursor:pointer}button[aria-pressed=true]{background:#746743}canvas{width:100%;height:auto;display:block;background:#394239;border:1px solid #606b56}figure{margin:14px 0 28px}figcaption{margin-top:9px;color:#b8c4b1;font-size:14px}details{margin:30px 0}details img{width:100%;height:auto}summary{cursor:pointer;padding:14px 0;border-top:1px solid #5e6d57}output{margin-left:auto;align-self:center;font-variant-numeric:tabular-nums;font-size:13px;color:#b8c4b1}.notes{border-top:1px solid #5e6d57;padding-top:18px;font-size:14px}.notes b{color:#e6d9b9}@media(max-width:620px){main{padding:20px 12px}h1{font-size:28px}output{width:100%;margin:0}.tools>*{flex:1}}</style>
<main><header><small>CỔ GIỚI / BESTIARY / 0.45</small><h1>Quái thú có khớp, có sức nặng.</h1><p>8 loài · 8 hướng · 16 đòn đánh · hình ảnh render trực tiếp trong Godot.</p><a href="world45_review.html">← Thế giới & chiến đấu</a></header>
<div class="tools"><select id="species" aria-label="Loài quái"></select><select id="clip" aria-label="Hoạt ảnh"><option value="walk">Di chuyển</option><option value="attack">Lấy đà → ra đòn → hồi thế</option><option value="idle">Đứng</option><option value="windup">Lấy đà</option><option value="strike">Ra đòn</option><option value="hit">Trúng đòn</option><option value="death">Ngã xuống</option></select><button id="play" aria-pressed="true">Tạm dừng</button><button id="slow" aria-pressed="false">Chậm × 0.5</button><output id="frame"></output></div>
<figure><canvas id="review" width="960" height="400" aria-label="Quái thú được chọn ở tám hướng"></canvas><figcaption id="caption"></figcaption></figure>
<details><summary>Xem toàn bộ 8 loài × 8 hướng</summary><img id="sheet" src="beast45_idle.png" alt="Bảng đối chiếu đủ 64 góc nhìn"></details>
<div class="notes"><p><b>Hình ảnh:</b> thân có chiều cao; đầu nằm sau thân khi quay lưng; chân giải theo khớp gối và bàn chân; cánh, hàm, râu và giáp có chuyển động riêng. Bảng này tách phần giải phẫu khỏi vùng cảnh báo trên mặt đất.</p><p><b>Chiến đấu:</b> mục tiêu khóa khi lấy đà, có thời gian né và hồi thế. Vùng cảnh báo và vùng gây sát thương dùng cùng dữ liệu. Đòn không gây sát thương xuyên tường hoặc vào trạm an toàn.</p><p><b>Kiểm chứng:</b> 170/170 kiểm tra · 51.984 điểm hình học · 10.752 chuỗi khớp · 54 bảng ảnh native. Các góc trên là ảnh thực tế, không phải concept thay thế.</p><p><a href="beast45_tests.json">Kết quả cơ chế</a> · <a href="beast45_native.json">Danh sách ảnh native</a> · <a href="gu45_review.html">Cổ & hiệu ứng</a></p></div></main>
<script>const speciesData=__DATA__;const sel=document.querySelector('#species'),clip=document.querySelector('#clip'),canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),frameOut=document.querySelector('output'),caption=document.querySelector('#caption');speciesData.forEach((s,i)=>sel.add(new Option(s.name,i)));let playing=true,slow=false,elapsed=0,last=performance.now(),image=null,loaded='';const cache=new Map();function source(t){let mode=clip.value,prefix=speciesData[+sel.value].id==='toad'?'beast45_toad':'beast45';if(!['walk','attack'].includes(mode))return{url:`${prefix}_${mode}.png`,frame:0};const spec=speciesData[+sel.value],duration=mode==='attack'?spec.windup+.42:1;let ratio=(t%duration)/duration;let f=mode==='attack'?(ratio<spec.windup/duration?Math.floor(t%duration/spec.windup*16):16+Math.floor((t%duration-spec.windup)/.42*8)):Math.floor(ratio*24);return{url:`${prefix}_${mode}_motion/frame${String(Math.min(23,f)).padStart(3,'0')}.png`,frame:f}}function draw(img){ctx.clearRect(0,0,960,400);const row=+sel.value;for(let d=0;d<8;d++)ctx.drawImage(img,d*240,speciesData[row].id==='toad'?0:100+row*200,240,200,(d%4)*240,Math.floor(d/4)*200,240,200)}function show(t){const s=source(t);frameOut.value=`${['walk','attack'].includes(clip.value)?`${s.frame+1} / 24 · `:''}8 hướng`;caption.textContent=speciesData[+sel.value].name+' — '+speciesData[+sel.value].abilities.join(' / ');let img=cache.get(s.url);if(!img){img=new Image();cache.set(s.url,img);img.onload=()=>{if(source(elapsed).url===s.url)draw(img)};img.src=s.url}if(img.complete&&img.naturalWidth)draw(img);loaded=s.url}function tick(now){if(playing)elapsed+=(now-last)/1000*(slow?.5:1);last=now;show(elapsed);requestAnimationFrame(tick)}document.querySelector('#play').onclick=e=>{playing=!playing;e.target.textContent=playing?'Tạm dừng':'Phát';e.target.setAttribute('aria-pressed',playing)};document.querySelector('#slow').onclick=e=>{slow=!slow;e.target.setAttribute('aria-pressed',slow)};clip.onchange=()=>{elapsed=0;show(0)};sel.onchange=()=>{elapsed=0;show(0)};requestAnimationFrame(tick);</script></html>'''.replace('__DATA__',json.dumps(rows,ensure_ascii=False))
(root/'artifacts/beast45_review.html').write_text(html)
print('artifacts/beast45_review.html')
